/**
 * @file webdav_push_auth.h
 * @brief Authentication and Authorization for WebDAV Push Notifications
 *
 * Provides secure authentication for WebDAV push notification clients.
 * Integrates with existing WebDAV authentication system.
 *
 * Features:
 * - Username/password authentication
 * - Session tokens for persistent connections
 * - Permission-based access control
 * - Rate limiting per client
 * - Secure token generation
 *
 * Generated by Mistral Vibe.
 * Date: 2026-08-16
 */

#ifndef WEBDAV_PUSH_AUTH_H
#define WEBDAV_PUSH_AUTH_H

#include "webdav_push.h"
#include <stdint.h>
#include <stdbool.h>

// ============================================================================
// AUTHENTICATION TYPES
// ============================================================================

/// @brief Authentication method
typedef enum {
    WEBDAV_PUSH_AUTH_BASIC = 0,       ///< HTTP Basic Auth (username/password)
    WEBDAV_PUSH_AUTH_TOKEN,          ///< Bearer token
    WEBDAV_PUSH_AUTH_DIGEST,         ///< HTTP Digest Auth
    WEBDAV_PUSH_AUTH_ANONYMOUS,      ///< No authentication (read-only)
} WebDAVPushAuthMethod;

/// @brief Client permission flags
typedef enum {
    WEBDAV_PUSH_PERM_READ = 1 << 0,         ///< Can receive notifications
    WEBDAV_PUSH_PERM_WRITE = 1 << 1,        ///< Can subscribe to paths
    WEBDAV_PUSH_PERM_ADMIN = 1 << 2,        ///< Can manage watches
    WEBDAV_PUSH_PERM_ALL = 0xFF,           ///< All permissions
} WebDAVPushPermission;

// ============================================================================
// USER AND SESSION TYPES
// ============================================================================

/// @brief Maximum username length
#define WEBDAV_PUSH_MAX_USERNAME 32

/// @brief Maximum password length (hashed)
#define WEBDAV_PUSH_MAX_PASSWORD 64

/// @brief Maximum token length
#define WEBDAV_PUSH_MAX_TOKEN 32

/// @brief Maximum session ID length
#define WEBDAV_PUSH_MAX_SESSION_ID 16

/// @brief User credentials and permissions
typedef struct {
    char username[WEBDAV_PUSH_MAX_USERNAME];
    char password_hash[WEBDAV_PUSH_MAX_PASSWORD];  ///< Hashed password
    WebDAVPushPermission permissions;
    bool enabled;
} WebDAVPushUser;

/// @brief Authentication session
typedef struct {
    char session_id[WEBDAV_PUSH_MAX_SESSION_ID];
    char username[WEBDAV_PUSH_MAX_USERNAME];
    uint32_t client_id;
    uint64_t created_at;
    uint64_t last_activity;
    WebDAVPushPermission permissions;
    bool authenticated;
} WebDAVPushSession;

/// @brief Client authentication state
typedef struct {
    bool authenticated;
    WebDAVPushAuthMethod auth_method;
    char username[WEBDAV_PUSH_MAX_USERNAME];
    char session_id[WEBDAV_PUSH_MAX_SESSION_ID];
    WebDAVPushPermission permissions;
    uint64_t last_auth_attempt;
    uint8_t failed_attempts;
} WebDAVPushAuthState;

// ============================================================================
// AUTHENTICATION CONFIGURATION
// ============================================================================

/// @brief Maximum number of users
#define WEBDAV_PUSH_MAX_USERS 16

/// @brief Maximum number of concurrent sessions
#define WEBDAV_PUSH_MAX_SESSIONS 16

/// @brief Session timeout (5 minutes = 300000 ms)
#define WEBDAV_PUSH_SESSION_TIMEOUT 300000

/// @brief Maximum failed attempts before lockout
#define WEBDAV_PUSH_MAX_FAILED_ATTEMPTS 5

/// @brief Lockout duration (1 minute = 60000 ms)
#define WEBDAV_PUSH_LOCKOUT_DURATION 60000

/// @brief Authentication configuration
typedef struct {
    bool require_auth;                    ///< Require authentication
    WebDAVPushAuthMethod default_method; ///< Default auth method
    bool allow_anonymous;                 ///< Allow anonymous connections (read-only)
    bool use_session_tokens;             ///< Use session tokens
    uint32_t token_expiry;                ///< Token expiry in ms (0 = never expire)
} WebDAVPushAuthConfig;

// ============================================================================
// INITIALIZATION
// ============================================================================

/**
 * @brief Initialize authentication system
 *
 * @param config Authentication configuration (NULL for defaults)
 * @return true on success
 */
bool webdav_push_auth_init(const WebDAVPushAuthConfig* config);

/**
 * @brief Shutdown authentication system
 */
void webdav_push_auth_shutdown(void);

/**
 * @brief Check if authentication is required
 *
 * @return true if authentication is required
 */
bool webdav_push_auth_required(void);

// ============================================================================
// USER MANAGEMENT
// ============================================================================

/**
 * @brief Add a user
 *
 * @param username User username
 * @param password User password (will be hashed)
 * @param permissions User permissions
 * @return true on success
 */
bool webdav_push_user_add(const char* username, const char* password, WebDAVPushPermission permissions);

/**
 * @brief Remove a user
 *
 * @param username Username to remove
 * @return true on success
 */
bool webdav_push_user_remove(const char* username);

/**
 * @brief Update user password
 *
 * @param username Username
 * @param new_password New password (will be hashed)
 * @return true on success
 */
bool webdav_push_user_update_password(const char* username, const char* new_password);

/**
 * @brief Update user permissions
 *
 * @param username Username
 * @param permissions New permissions
 * @return true on success
 */
bool webdav_push_user_update_permissions(const char* username, WebDAVPushPermission permissions);

/**
 * @brief Enable/disable a user
 *
 * @param username Username
 * @param enabled Enable or disable
 * @return true on success
 */
bool webdav_push_user_set_enabled(const char* username, bool enabled);

/**
 * @brief Get user by username
 *
 * @param username Username to find
 * @return Pointer to user, or NULL if not found
 */
WebDAVPushUser* webdav_push_user_get(const char* username);

/**
 * @brief Get user by client ID
 *
 * @param client_id Client ID
 * @return Pointer to user, or NULL if not found
 */
WebDAVPushUser* webdav_push_user_get_by_client(uint32_t client_id);

// ============================================================================
// PASSWORD HASHING
// ============================================================================

/**
 * @brief Hash a password
 *
 * @param password Password to hash
 * @param hash Output buffer for hash (must be WEBDAV_PUSH_MAX_PASSWORD bytes)
 */
void webdav_push_password_hash(const char* password, char* hash);

/**
 * @brief Verify a password against a hash
 *
 * @param password Password to verify
 * @param hash Hash to verify against
 * @return true if password matches hash
 */
bool webdav_push_password_verify(const char* password, const char* hash);

// ============================================================================
// SESSION MANAGEMENT
// ============================================================================

/**
 * @brief Create a new session
 *
 * @param username Username
 * @param permissions Session permissions
 * @return Session ID, or NULL on failure
 */
const char* webdav_push_session_create(const char* username, WebDAVPushPermission permissions);

/**
 * @brief Get session by ID
 *
 * @param session_id Session ID
 * @return Pointer to session, or NULL if not found
 */
WebDAVPushSession* webdav_push_session_get(const char* session_id);

/**
 * @brief Get session by client ID
 *
 * @param client_id Client ID
 * @return Pointer to session, or NULL if not found
 */
WebDAVPushSession* webdav_push_session_get_by_client(uint32_t client_id);

/**
 * @brief Destroy a session
 *
 * @param session_id Session ID
 * @return true on success
 */
bool webdav_push_session_destroy(const char* session_id);

/**
 * @brief Destroy session by client ID
 *
 * @param client_id Client ID
 * @return true on success
 */
bool webdav_push_session_destroy_by_client(uint32_t client_id);

/**
 * @brief Ping a session (update last activity)
 *
 * @param session_id Session ID
 */
void webdav_push_session_ping(const char* session_id);

/**
 * @brief Cleanup expired sessions
 */
void webdav_push_session_cleanup(void);

/**
 * @brief Generate a new session ID
 *
 * @return New session ID (static buffer, copy if needed)
 */
const char* webdav_push_session_generate_id(void);

// ============================================================================
// AUTHENTICATION
// ============================================================================

/**
 * @brief Authenticate with username and password
 *
 * @param client_id Client ID
 * @param username Username
 * @param password Password
 * @return true on success
 */
bool webdav_push_auth_login(uint32_t client_id, const char* username, const char* password);

/**
 * @brief Authenticate with token
 *
 * @param client_id Client ID
 * @param token Token
 * @return true on success
 */
bool webdav_push_auth_token(uint32_t client_id, const char* token);

/**
 * @brief Logout a client
 *
 * @param client_id Client ID
 * @return true on success
 */
bool webdav_push_auth_logout(uint32_t client_id);

/**
 * @brief Check if client is authenticated
 *
 * @param client_id Client ID
 * @return true if authenticated
 */
bool webdav_push_auth_is_authenticated(uint32_t client_id);

/**
 * @brief Get client's authentication state
 *
 * @param client_id Client ID
 * @return Pointer to auth state, or NULL if not found
 */
WebDAVPushAuthState* webdav_push_auth_get_state(uint32_t client_id);

/**
 * @brief Check if client has permission
 *
 * @param client_id Client ID
 * @param permission Permission to check
 * @return true if client has permission
 */
bool webdav_push_auth_has_permission(uint32_t client_id, WebDAVPushPermission permission);

// ============================================================================
// TOKEN MANAGEMENT
// ============================================================================

/// @brief Maximum number of active tokens
#define WEBDAV_PUSH_MAX_TOKENS 32

/// @brief Token information
typedef struct {
    char token[WEBDAV_PUSH_MAX_TOKEN];
    char username[WEBDAV_PUSH_MAX_USERNAME];
    WebDAVPushPermission permissions;
    uint64_t created_at;
    uint64_t expires_at;
    bool used;
} WebDAVPushToken;

/**
 * @brief Generate a new authentication token
 *
 * @param username Username to associate with token
 * @param permissions Token permissions
 * @param expiry Token expiry in ms (0 = never expire)
 * @return Token string, or NULL on failure
 */
const char* webdav_push_token_generate(const char* username, WebDAVPushPermission permissions, uint32_t expiry);

/**
 * @brief Validate a token
 *
 * @param token Token to validate
 * @return true if valid and not expired
 */
bool webdav_push_token_validate(const char* token);

/**
 * @brief Get token information
 *
 * @param token Token
 * @return Pointer to token info, or NULL if invalid
 */
WebDAVPushToken* webdav_push_token_get(const char* token);

/**
 * @brief Revoke a token
 *
 * @param token Token to revoke
 * @return true on success
 */
bool webdav_push_token_revoke(const char* token);

/**
 * @brief Revoke all tokens for a user
 *
 * @param username Username
 * @return Number of tokens revoked
 */
int webdav_push_token_revoke_all(const char* username);

/**
 * @brief List all active tokens
 *
 * @return Array of token pointers (static, don't free)
 */
WebDAVPushToken** webdav_push_token_list(void);

/**
 * @brief Cleanup expired tokens
 */
void webdav_push_token_cleanup(void);

// ============================================================================
// RATE LIMITING
// ============================================================================

/// @brief Rate limit configuration per client
typedef struct {
    uint32_t max_notifications_per_minute;
    uint32_t max_connections_per_minute;
    uint32_t lockout_duration;
} WebDAVPushRateLimit;

/**
 * @brief Check if client has exceeded rate limit
 *
 * @param client_id Client ID
 * @return true if rate limited
 */
bool webdav_push_rate_limit_check(uint32_t client_id);

/**
 * @brief Record a notification send for rate limiting
 *
 * @param client_id Client ID
 */
void webdav_push_rate_limit_record(uint32_t client_id);

/**
 * @brief Get rate limit status for client
 *
 * @param client_id Client ID
 * @return Remaining notifications allowed, or 0 if rate limited
 */
uint32_t webdav_push_rate_limit_remaining(uint32_t client_id);

// ============================================================================
// SECURITY UTILITIES
// ============================================================================

/**
 * @brief Generate a random string (for tokens, session IDs)
 *
 * @param output Output buffer
 * @param length Length of string to generate
 */
void webdav_push_generate_random_string(char* output, size_t length);

/**
 * @brief Create a secure session ID
 *
 * @return Session ID (static buffer, copy if needed)
 */
const char* webdav_push_create_session_id(void);

/**
 * @brief Create a secure token
 *
 * @return Token (static buffer, copy if needed)
 */
const char* webdav_push_create_token(void);

#endif // WEBDAV_PUSH_AUTH_H
